You assess retrieved reference tests for unit-test generation.
A generator must write a Hardhat (ethers 6, Mocha/Chai) unit-test suite for the TARGET Solidity contract below.
It receives example tests retrieved from a corpus of OTHER contracts. Such examples are never written for the target:
a different contract name is expected and is NOT a reason for a low rating. Judge only their value as a template.

Rate the RETRIEVED TEST:
2 = directly adaptable: it exercises a behaviour that the target also implements (same kind of operation, state change,
    access rule or revert condition); its setup, calls, assertions or revert checks could be reused after renaming.
1 = partially useful: it shows a generic testing pattern applicable to the target (e.g., access-control revert, event
    assertion, time manipulation, balance change, deployment with constructor arguments), but the specific behaviour it
    tests does not exist in the target.
0 = not useful: neither its behaviour nor its testing pattern applies to the target.

Give a reason of at most 30 words, then the rating.

TARGET CONTRACT:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract Adoption {
    address[16] public adopters;

    function adopt(uint256 petId) external returns (uint256) {
        require(petId < 16, "invalid pet");
        adopters[petId] = msg.sender;
        return petId;
    }

    function getAdopters() external view returns (address[16] memory) {
        return adopters;
    }
}

RETRIEVED TEST:
// corpus-v2 pair griffin-dex--littlefingerrr (amm-dex, moderate)
// GriffinDEX.test.js: GriffinDEX > getReserves > returns correct reserves after adding liquidity
const { expect } = require("chai");
const { ethers } = require("hardhat");
let dex;
let tokenA;
let tokenB;
let owner;
let lp;
let trader;
let recipient;
const INITIAL_SUPPLY = 1_000_000n;
const LIQUIDITY_A = ethers.parseUnits("10000", 18);
const LIQUIDITY_B = ethers.parseUnits("10000", 6);
// beforeEach of suite "GriffinDEX"
beforeEach(async () => {
    [owner, lp, trader, recipient] = await ethers.getSigners();

    const MockERC20Factory = await ethers.getContractFactory("MockERC20");
    tokenA = await MockERC20Factory.deploy("Token A", "TKA", 18, INITIAL_SUPPLY);
    tokenB = await MockERC20Factory.deploy("Token B", "TKB", 6, INITIAL_SUPPLY);

    const GriffinDEXFactory = await ethers.getContractFactory("GriffinDEX");
    dex = await GriffinDEXFactory.deploy();

    // Fund lp and trader with tokens
    await tokenA.transfer(lp.address, LIQUIDITY_A * 2n);
    await tokenB.transfer(lp.address, LIQUIDITY_B * 2n);
    await tokenA.transfer(trader.address, ethers.parseUnits("1000", 18));
  })
it("returns correct reserves after adding liquidity", async () => {
      await dex.createPool(tokenA.target, tokenB.target);
      await tokenA.connect(lp).approve(dex.target, LIQUIDITY_A);
      await tokenB.connect(lp).approve(dex.target, LIQUIDITY_B);
      await dex.connect(lp).addLiquidity(tokenA.target, tokenB.target, LIQUIDITY_A, LIQUIDITY_B);

      const [reserveA, reserveB] = await dex.getReserves(tokenA.target, tokenB.target);
      expect(reserveA).to.equal(LIQUIDITY_A);
      expect(reserveB).to.equal(LIQUIDITY_B);
    })


